package com.bank.pkce;

import java.security.MessageDigest;
import java.security.SecureRandom;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.logging.*;

public class PkceFlowDemo {
    private static final Logger log = Logger.getLogger(PkceFlowDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PkceClient app = new PkceClient();
        AuthorizationServer authServer = new AuthorizationServer();

        // 1. Client generates verifier + challenge (challenge = SHA256(verifier)).
        String verifier = app.newCodeVerifier();
        String challenge = app.challengeFor(verifier);
        log.info(() -> "Client generated verifier (secret) and challenge (public hash)");

        // 2. Authorize request sends ONLY the challenge; server stores it with the code.
        String code = authServer.issueCode("rajesh", challenge);
        log.info(() -> "Auth server returned code bound to challenge");

        // 3. Token exchange sends the original verifier; server re-hashes and compares.
        String token = authServer.exchange(code, verifier);
        log.info(() -> "Legitimate app exchanged code -> access token: " + token);

        // Attacker intercepted the code but has a WRONG verifier -> rejected.
        String attackerVerifier = app.newCodeVerifier();
        String freshCode = authServer.issueCode("rajesh", challenge);
        try {
            authServer.exchange(freshCode, attackerVerifier);
        } catch (PkceValidationException e) {
            log.severe("Attacker with stolen code but wrong verifier rejected: " + e.getMessage());
        }
    }
}

// ─── Would be in PkceClient.java ───
class PkceClient {
    private final SecureRandom rnd = new SecureRandom();
    String newCodeVerifier() {
        byte[] b = new byte[32];
        rnd.nextBytes(b);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(b);
    }
    String challengeFor(String verifier) {
        try {
            byte[] hash = MessageDigest.getInstance("SHA-256")
                .digest(verifier.getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(hash);
        } catch (Exception e) { throw new RuntimeException(e); }
    }
}

// ─── Would be in PkceValidationException.java ───
class PkceValidationException extends RuntimeException {
    PkceValidationException(String m) { super(m); }
}

// ─── Would be in AuthorizationServer.java ───
class AuthorizationServer {
    private final Map<String, String[]> codes = new HashMap<>(); // code -> {user, challenge}
    private final PkceClient hasher = new PkceClient();

    String issueCode(String username, String codeChallenge) {
        String code = "code-" + UUID.randomUUID();
        codes.put(code, new String[]{username, codeChallenge});
        return code;
    }

    String exchange(String code, String codeVerifier) {
        String[] rec = codes.remove(code); // single use
        if (rec == null) throw new PkceValidationException("invalid or used code");
        String recomputed = hasher.challengeFor(codeVerifier);
        if (!recomputed.equals(rec[1]))
            throw new PkceValidationException("PKCE verifier does not match challenge");
        return "access-token-for-" + rec[0];
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
